import json

pairs = {'(': ')', '[': ']', '{': '}', '<': '>'}
closers = set(pairs.values())

s = "< ( ( [ < > { [ { ( ) } ] < { < { } > [ ( < > ) ] } > } [ < > ] ] ) { { ( { ( ( [ ( [ ] ) ] < { } > ) ) { { ( [ [ ] ] ) } [ ( ) ] { { [ ] } } } } ) } ( { } ) }"
tokens = s.split()

stack = []
valid = True
bad_index = None
for i, t in enumerate(tokens):
    if t in pairs:
        stack.append(t)
    elif t in closers:
        if not stack or pairs[stack[-1]] != t:
            valid = False
            bad_index = i
            break
        stack.pop()
    else:
        valid = False
        bad_index = i
        break

if not valid:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {"reason": "mismatched or invalid token", "index": bad_index}
    }
else:
    completion = ''.join(pairs[o] for o in reversed(stack))
    result = {
        "final_answer": completion,
        "evidence": {
            "tokens": len(tokens),
            "unclosed_stack": ''.join(stack),
            "completion_length": len(completion)
        }
    }

print(json.dumps(result, separators=(",", ":")))
